mapper.select:
SELECT e.id, e.equipment_name AS equipmentName, e.equipment_type AS equipmentType, e.rated_params AS ratedParams, e.install_location AS installLocation, e.manufacture_date AS manufactureDate, e.impact_scope AS impactScope, e.hazard_level AS hazardLevel, e.install_batch AS installBatch, e.quantity, e.commission_batch AS commissionBatch, e.substation_id AS substationId, s.name AS substationName FROM power_equipment e LEFT JOIN substation s ON e.substation_id = s.id
e.deleted = 0
AND e.equipment_name LIKE CONCAT('%', #{equipmentName}, '%')
AND e.equipment_type = #{equipmentType}
AND e.hazard_level = #{hazardLevel}
AND e.substation_id = #{substationId}
AND e.install_batch = #{installBatch}
ORDER BY e.create_time ASC

SELECT * FROM power_equipment

    deleted = 0

        AND equipment_name LIKE CONCAT('%', #{equipmentName}, '%')


        AND equipment_type = #{equipmentType}


        AND hazard_level = #{hazardLevel}


ORDER BY ${sortField} ${sortOrder} LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM power_equipment

    deleted = 0

        AND equipment_name LIKE CONCAT('%', #{equipmentName}, '%')


        AND equipment_type = #{equipmentType}


        AND hazard_level = #{hazardLevel}
